// Regenerates docs/INDEX-HEADINGS.md: heading -> line number for the large authority documents,
// so a task opens only the sections it needs (CLAUDE.md "Reading order"). Run: node scripts/build-docs-index.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const DOCS = [
	['PROJECT_DECISIONS.md', 2],
	['docs/brief/CLAVERA_Site_TZ_v1_5.md', 2],
	['docs/project/CLAVERA_EXECUTION_PLAN.md', 2],
	['docs/project/CLAVERA_WORKLOG.md', 2],
];

const out = [
	'# Heading map (generated by scripts/build-docs-index.mjs; do not edit by hand)',
	'',
	'Format: `line  heading`. Open a file with an offset/limit around the line you need.',
	'',
];
for (const [file, maxDepth] of DOCS) {
	const lines = readFileSync(file, 'utf8').split('\n');
	out.push(`## ${file} (${lines.length} lines)`, '');
	let inFence = false;
	lines.forEach((line, i) => {
		if (line.startsWith('```')) inFence = !inFence;
		const m = !inFence && /^(#{1,6}) (.+)/.exec(line);
		if (m && m[1].length <= maxDepth) out.push(`${i + 1}  ${m[2].slice(0, 80).trimEnd()}`);
	});
	out.push('');
}
writeFileSync('docs/INDEX-HEADINGS.md', out.join('\n'));
